create type public.decision_status as enum('rascunho','aberta','aprovada','reprovada','cancelada');create type public.approval_rule as enum('unanimidade','maioria','socio_presente','livre');create type public.vote_choice as enum('favor','contra','abstencao');
create table public.decisoes(id uuid primary key default gen_random_uuid(),titulo text not null,descricao text not null,solicitante_id uuid not null references public.profiles(id) on delete restrict,justificativa text,impacto_financeiro bigint,participantes uuid[] not null default '{}',regra_aprovacao public.approval_rule not null default 'maioria',status public.decision_status not null default 'aberta',prazo timestamptz,historico jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_decisoes_status on public.decisoes(status);create index idx_decisoes_solicitante on public.decisoes(solicitante_id);
create trigger decisoes_updated_at before update on public.decisoes for each row execute function public.tocar_updated_at();
create function public.decisao_registrar_evento() returns trigger language plpgsql set search_path=public as $$ declare evento jsonb;begin if tg_op='INSERT' then evento=jsonb_build_object('evento','criada','usuarioId',new.solicitante_id,'detalhe','Solicitação aberta','em',now());new.historico=new.historico||jsonb_build_array(evento);elsif tg_op='UPDATE' and new.status is distinct from old.status then evento=jsonb_build_object('evento',new.status,'usuarioId',auth.uid(),'detalhe',concat('Status: ',old.status,' → ',new.status),'em',now());new.historico=new.historico||jsonb_build_array(evento);end if;return new;end; $$;
create trigger decisoes_evento before insert or update on public.decisoes for each row execute function public.decisao_registrar_evento();
create function public.proteger_historico() returns trigger language plpgsql set search_path=public as $$ begin if new.historico is distinct from old.historico then raise exception 'O histórico da decisão é gerenciado pelo sistema';end if;return new;end; $$;
create trigger decisoes_01_protege_historico before update on public.decisoes for each row execute function public.proteger_historico();
create table public.decisao_votos(decisao_id uuid not null references public.decisoes(id) on delete cascade,socio_id uuid not null references public.profiles(id) on delete cascade,voto public.vote_choice not null,comentario text,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now(),primary key(decisao_id,socio_id));
create index idx_decisao_votos_socio on public.decisao_votos(socio_id);
create function public.tocar_voto_atualizado_em() returns trigger language plpgsql set search_path=public as $$ begin new.atualizado_em=now();return new;end; $$;
create trigger decisao_votos_updated_at before update on public.decisao_votos for each row execute function public.tocar_voto_atualizado_em();
alter table public.decisao_votos enable row level security;
create policy decisao_votos_interno_select on public.decisao_votos for select to authenticated using(public.eh_interno());
create policy decisao_votos_socio_insert on public.decisao_votos for insert to authenticated with check(socio_id=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('ceo','cro','coo_cfo')) and exists(select 1 from public.decisoes d where d.id=decisao_id and d.status='aberta'));
create policy decisao_votos_socio_update on public.decisao_votos for update to authenticated using(socio_id=auth.uid()) with check(socio_id=auth.uid() and exists(select 1 from public.decisoes d where d.id=decisao_id and d.status='aberta'));
revoke execute on function public.decisao_registrar_evento() from public,anon,authenticated;
revoke execute on function public.proteger_historico() from public,anon,authenticated;
revoke execute on function public.tocar_voto_atualizado_em() from public,anon,authenticated;
alter table public.decisoes enable row level security;
create policy decisoes_interno_select on public.decisoes for select to authenticated using(public.eh_interno());
create policy decisoes_socio_insert on public.decisoes for insert to authenticated with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('ceo','cro','coo_cfo')));
create policy decisoes_socio_update on public.decisoes for update to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('ceo','cro','coo_cfo'))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('ceo','cro','coo_cfo')));
